  class: net.officefloor.hq.app.claim.RecordClaimWaived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who waives the claim's late charge. */
public class ValidateWaive {
    public void validate(@RequestBody WaiveRequest request, Out<ClaimWaiver> waiver) {
        waiver.set(new ClaimWaiver(request == null || request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Val;

/** Checks a waiver: only a steward waives, only an OPEN or PENDING claim, and only one not already waived. */
public class ApplyWaive {
    public void apply(@Val Claim claim, @Val ClaimWaiver waiver, RoleRepository roles, ClaimRepository claims)
            throws InvalidClaimStatusException {
        if (!RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), waiver.by()))) {
            throw new InvalidClaimStatusException("Only a steward waives a late charge");
        }
        if (!ClaimDue.isOpen(claim)) {
            throw new InvalidClaimStatusException("Only an OPEN or PENDING claim's late charge can be waived");
        }
        if (claims.waivedOn(claim.sheetId(), claim.id()) != null) {
            throw new InvalidClaimStatusException("The claim's late charge is already waived");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores the waiver as made on the sheet's today, but only while the claim is still OPEN or PENDING and not waived; a
 *  change another user made first is refused. */
public class SaveWaive {
    public void save(@Val Claim claim, ClaimRepository claims, SheetRepository sheets) throws InvalidClaimStatusException {
        if (!claims.waive(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_WAIVED to the audit file once the waiver is stored, naming the claim (number=<number> when it has
 *  one), then the figures the change moved (see Rollup). */
public class RecordClaimWaived {
    public void record(@Val Claim claim, @Val ClaimWaiver waiver, PersonRepository people,
            @Val RollupBefore before, Rollup rollup, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_WAIVED sheet=" + claim.sheetId() + " by=" + waiver.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (claim.number() == null ? "" : " number=" + claim.number()));
        rollup.record(claim.sheetId(), waiver.by(), before);
    }
}
package net.officefloor.hq.app.claim;

/** Body of waiving a claim's late charge: who waives it. */
public record WaiveRequest(String by) {
}
package net.officefloor.hq.app.claim;

/** A waiver of a claim's late charge once its body is read: who waives it. */
public record ClaimWaiver(String by) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id; one not on the sheet is a 404. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository claims, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found;
        try {
            found = claims.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new ClaimNotFoundException("No claim " + claimId);
        }
        claim.set(found);
    }
}

