# GET /api/sheets/{sheetId}/claims — every claim on the sheet as the store holds it, newest first.
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's claims, newest first, each with its status log. Read as of a date (see AsOf), each as it stood then:
 *  one added later is left out; its amount, date and note are those it had before any later edit; its status, and its log, are those its log shows then; its comments are those written by then; its lines are those added by then; its proofs count leaves out the proofs added after; its deferral is the last one made by then; it has the number and opener
 *  only once opened by then, its settled due only while SETTLED then, and is bound only when its person's last
 *  statement was taken while the sheet's today was on or before the date; the date stands in for today. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, ClaimRepository claims,
            ClaimLogRepository log, SheetRepository sheets, StatementRepository statements,
            ObjectResponse<List<ClaimResponse>> response) {
        String sheet = sheetId.trim();
        LocalDate date = AsOf.parse(asOf);
        Map<Long, List<ClaimLogLine>> logs = log.bySheet(sheet);
        LocalDate today = date == null ? sheets.today(sheet) : date;
        Map<Long, String> locks = claims.locks(sheet);
        Map<Long, Long> seqs = claims.addedSeqs(sheet);
        Set<Long> late = claims.lateEntries(sheet);
        Map<Long, LocalDate> reminded = claims.reminders(sheet, date);
        Map<Long, List<ClaimComment>> comments = claims.comments(sheet, date);
        Map<Long, Integer> batches = claims.batches(sheet, date);
        Set<Long> waived = claims.waived(sheet, date);
        Map<Long, List<ClaimLine>> lineItems = claims.lines(sheet, date);
        Map<Long, Claim> edited = date == null ? Map.of() : claims.editedAfter(sheet, date);
        Map<Long, Integer> proofsAfter = date == null ? Map.of() : claims.proofsAfter(sheet, date);
        Map<Long, LocalDate> deferred = date == null ? Map.of() : claims.deferredAsOf(sheet, date);
        List<ClaimResponse> out = new ArrayList<>();
        for (Claim c : claims.list(sheet)) {
            List<ClaimLogLine> lines = logs.getOrDefault(c.id(), List.of());
            Claim shown = c;
            if (date != null) {
                lines = lines.stream().filter((l) -> !l.date().isAfter(date)).toList();
                if (lines.isEmpty() && !logs.getOrDefault(c.id(), List.of()).isEmpty()) {
                    continue;
                }
                shown = asItStood(c, edited.get(c.id()), proofsAfter.getOrDefault(c.id(), 0),
                        deferred.containsKey(c.id()) ? deferred.get(c.id()) : c.deferredUntil(), lines, date, statements);
            }
            out.add(ClaimResponse.from(shown, claims, lines, today, date == null ? locks.get(c.id()) : null,
                    late.contains(c.id()), reminded.get(c.id()), comments.getOrDefault(c.id(), List.of()),
                    batches.get(c.id()), lineItems.getOrDefault(c.id(), List.of()), seqs.getOrDefault(c.id(), 0L), waived.contains(c.id())));
        }
        response.send(out);
    }

    /** The claim as it stood at the end of the date, its log (oldest first) cut there, with the values it had before
     *  its first edit after the date (null: none), without the proofs added after it and deferred until the date given. */
    private static Claim asItStood(Claim c, Claim before, int proofsAfter, LocalDate deferredUntil, List<ClaimLogLine> lines, LocalDate date, StatementRepository statements) {
        ClaimStatus status = lines.isEmpty() ? c.status() : lines.get(lines.size() - 1).status();
        boolean opened = lines.isEmpty() || lines.stream().anyMatch((l) -> l.status() == ClaimStatus.OPEN);
        // Opening a claim may send it to REVIEW instead of OPEN: it was opened all the same.
        boolean openedBy = opened || lines.stream().anyMatch((l) -> l.status() == ClaimStatus.REVIEW);
        Statement last = c.stated() ? statements.last(c.sheetId(), c.personId()) : null;
        boolean stated = last != null && AsOf.counts(last.madeOn(), date);
        Claim values = before == null ? c : before;
        return new Claim(c.id(), c.sheetId(), c.personId(), values.amount(), values.date(), values.note(), status,
                opened ? c.number() : null, status == ClaimStatus.SETTLED ? c.due() : null, openedBy ? c.openedBy() : null,
                stated, stated ? c.statedDue() : null, values.corrects(), c.dueBy(), deferredUntil, c.proofs() - proofsAfter,
                c.splitFrom(), values.ref(), values.tags(), c.held());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
 *  live; openedBy is who opened it, null when never opened; stated is whether it is bound to the figure statedDue
 *  (two decimals, null when it had none) by its person's last statement; corrects is the number of the claim a
 *  correction corrects (null for any other claim); roundsOn is the date that decides how its live figures round
 *  (the corrected claim's date for a correction, else its own; see Rounding); dueBy (yyyy-MM-dd) is its due-by, fixed
 *  when it was added; deferred is whether it is deferred on the sheet's today (see ClaimDue#deferred) and deferredUntil
 *  (yyyy-MM-dd) the date it was last deferred until (shown even once that date has passed), null when never deferred; proofs is its proofs count, proofsReceipt and proofsPhoto how many of them are receipts and photos; splitFrom is the number of the claim it was split from (null for any other claim); log is its status log, oldest first: each status it has had, who made the change, the sheet's
 *  today (yyyy-MM-dd) then, and its due as shown at that moment (two decimals, or n/a); lockedBy is who has its editor
 *  open (null when no one does); lateEntry is whether it was added while its period was soft-closed; reminded (yyyy-MM-dd) is the last day a
 *  reminder was written for it, null when none; ref is its external reference, null when none; tags are its tags, sorted (empty when none); comments are its comments in the order written, each with who wrote it and
 *  the sheet's today (yyyy-MM-dd) then; batch is the number of the bulk settle batch that settled it, null when none did; lines are its lines in the order added (empty when none); seq is the order it was added in, across every sheet (a
 *  forward-only rate applies only to claims whose seq is above its after; see Rate#appliesTo); waived is whether a steward waived its late charge
 *  (see ApplyWaive); held is whether it is held (see ApplyClaimHold). */
public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String dueBy, boolean deferred, String deferredUntil, int proofs, int proofsReceipt, int proofsPhoto, String splitFrom, List<LogLine> log,
        String lockedBy, boolean lateEntry, String reminded, String ref, List<String> tags,
        List<Comment> comments, Integer batch, List<Line> lines, long seq, boolean waived, boolean held) {

    /** One line of a claim as sent to the screen: its label, quantity and unit amount (two decimals). */
    public record Line(String label, int qty, String unit) {
    }

    /** One comment on a claim as sent to the screen. */
    public record Comment(String by, String date, String text) {
    }

    /** One line of a claim's status log as sent to the screen. */
    public record LogLine(String status, String by, String date, String due) {
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, ClaimLogRepository log, LocalDate today) {
        return from(claim, claims, log.of(claim.sheetId(), claim.id()), today);
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today) {
        return from(claim, claims, log, today, claims.lockedBy(claim.sheetId(), claim.id()),
                claims.lateEntry(claim.sheetId(), claim.id()), claims.remindedOn(claim.sheetId(), claim.id()),
                claims.comments(claim.sheetId(), claim.id()), claims.batchOf(claim.sheetId(), claim.id()),
                claims.lines(claim.sheetId(), claim.id()), claims.addedSeq(claim.sheetId(), claim.id()),
                claims.waivedOn(claim.sheetId(), claim.id()) != null);
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today, String lockedBy,
            boolean lateEntry, LocalDate reminded, List<ClaimComment> comments, Integer batch, List<ClaimLine> lines,
            long seq, boolean waived) {
        boolean deferred = ClaimDue.deferred(claim, today);
        int photos = claims.photoProofs(claim);
        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                Rounding.roundsOn(claim, claims).toString(), claim.dueBy().toString(),
                deferred, claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(), claim.proofs() - photos, photos, claim.splitFrom(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                lockedBy, lateEntry, reminded == null ? null : reminded.toString(), claim.ref(),
                claim.tags() == null ? List.of() : List.of(claim.tags().split(",")),
                comments.stream().map((m) -> new Comment(m.by(), m.date().toString(), m.text())).toList(), batch,
                lines.stream().map((l) -> new Line(l.label(), l.qty(), l.unit().toPlainString())).toList(), seq, waived, claim.held());
    }
}

